_PATTERN = re.compile(r"(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?")
_MULTIPLIERS = (86400, 3600, 60, 1)


def parse_duration(s):
    """Convert a duration string like '1h30m' into an int number of seconds.

    Units are d, h, m and s, each appearing at most once and in that order.
    Amounts are non-negative integers. Surrounding whitespace is allowed.
    Raises ValueError for anything else.
    """
    if not isinstance(s, str):
        raise ValueError("duration must be a string")

    text = s.strip()
    if not text:
        raise ValueError("empty duration")

    match = _PATTERN.fullmatch(text)
    if match is None:
        raise ValueError("invalid duration: %r" % (s,))

    groups = match.groups()
    if all(g is None for g in groups):
        raise ValueError("invalid duration: %r" % (s,))

    total = 0
    for amount, multiplier in zip(groups, _MULTIPLIERS):
        if amount is not None:
            total += int(amount) * multiplier
    return total
